def applications(served: Served) -> Dict[str, ASGIApp]:
  """Each service's application, by the path its calls start with."""
  return {
    "/pylabrobot.hamilton.star.server.v1.STARService/": star_connect.STARServiceASGIApplication(STARHandlers(served)),
    "/pylabrobot.hamilton.star.server.v1.DriverService/": driver_connect.DriverServiceASGIApplication(DriverHandlers(served)),
    "/pylabrobot.hamilton.star.server.v1.PipettesService/": pipettes_connect.PipettesServiceASGIApplication(PipettesHandlers(served)),
    "/pylabrobot.hamilton.star.server.v1.Head96Service/": head96_connect.Head96ServiceASGIApplication(Head96Handlers(served)),
    "/pylabrobot.hamilton.star.server.v1.Head384Service/": head384_connect.Head384ServiceASGIApplication(Head384Handlers(served)),
    "/pylabrobot.hamilton.star.server.v1.ISwapService/": iswap_connect.ISwapServiceASGIApplication(ISwapHandlers(served)),
    "/pylabrobot.hamilton.star.server.v1.CoreGrippersService/": core_grippers_connect.CoreGrippersServiceASGIApplication(CoreGrippersHandlers(served)),
    "/pylabrobot.hamilton.star.server.v1.AutoloadService/": autoload_connect.AutoloadServiceASGIApplication(AutoloadHandlers(served)),
    "/pylabrobot.hamilton.star.server.v1.XArmService/": x_arm_connect.XArmServiceASGIApplication(XArmHandlers(served)),
    "/pylabrobot.hamilton.star.server.v1.FrontCoverService/": front_cover_connect.FrontCoverServiceASGIApplication(FrontCoverHandlers(served)),
  }
